package com.bank.statement.db;

import java.util.concurrent.Semaphore;
import java.util.concurrent.atomic.AtomicLong;

// Models PostgreSQL with a HARD connection ceiling.
// If more than the ceiling try to run, the extra are REFUSED (connection exhaustion).
public class PostgresLimit {
    private final Semaphore connections;
    private final AtomicLong served = new AtomicLong();
    private final AtomicLong refused = new AtomicLong();

    public PostgresLimit(int hardMax) { this.connections = new Semaphore(hardMax); }

    public boolean runQuery() {
        if (!connections.tryAcquire()) { refused.incrementAndGet(); return false; }
        try {
            Thread.sleep(20); // query time while holding a connection
            served.incrementAndGet();
            return true;
        } catch (InterruptedException e) { return false; }
        finally { connections.release(); }
    }
    public long served() { return served.get(); }
    public long refused() { return refused.get(); }
}
