package com.bank.statement.db;

// Models PgBouncer: ONE shared cap in front of PostgreSQL.
// No matter how many pods exist, the DB sees at most 'cap' concurrent queries.
public class SharedConnectionGate {
    private final java.util.concurrent.Semaphore gate;
    private final PostgresLimit db;
    public SharedConnectionGate(int cap, PostgresLimit db) {
        this.gate = new java.util.concurrent.Semaphore(cap); this.db = db;
    }
    public boolean query() {
        try {
            gate.acquire();           // wait for a shared slot, never exceed cap
            return db.runQuery();
        } catch (InterruptedException e) { return false; }
        finally { gate.release(); }
    }
}
