package com.bank.statement.pod;

import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicLong;
import java.util.function.Supplier;

// One Kubernetes replica. Each pod issues concurrent statement requests.
public class StatementPod {
    private final int requestsPerPod;
    private final AtomicLong ok = new AtomicLong();
    private final AtomicLong failed = new AtomicLong();

    public StatementPod(int requestsPerPod) { this.requestsPerPod = requestsPerPod; }

    public void run(Supplier<Boolean> queryFn) throws InterruptedException {
        ExecutorService pool = Executors.newFixedThreadPool(requestsPerPod);
        CountDownLatch latch = new CountDownLatch(requestsPerPod);
        for (int i = 0; i < requestsPerPod; i++) {
            pool.submit(() -> {
                if (queryFn.get()) ok.incrementAndGet(); else failed.incrementAndGet();
                latch.countDown();
            });
        }
        latch.await(10, TimeUnit.SECONDS);
        pool.shutdown();
    }
    public long ok() { return ok.get(); }
    public long failed() { return failed.get(); }
}
