package com.bank.statement;

import com.bank.statement.db.PostgresLimit;
import com.bank.statement.db.SharedConnectionGate;
import com.bank.statement.pod.StatementPod;
import java.util.logging.*;

public class AutoscaleDemo {
    private static final Logger log = Logger.getLogger(AutoscaleDemo.class.getName());
    static {
        LogManager.getLogManager().reset();
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.addHandler(h); log.setLevel(Level.INFO);
    }
    public static void main(String[] args) throws Exception {
        int[] podCounts = {3, 6, 12, 24}; // autoscaler keeps adding replicas

        log.info("=== NAIVE: autoscale pods, NO shared cap (DB ceiling=12) ===");
        for (int pods : podCounts) {
            PostgresLimit db = new PostgresLimit(12);
            runFleet(pods, () -> db.runQuery());
            log.warning(() -> "pods=" + pods + " served=" + db.served()
                    + " REFUSED=" + db.refused() + " (more pods → more refusals)");
        }

        log.info("=== FIXED: PgBouncer-style shared gate caps DB at 12 ===");
        for (int pods : podCounts) {
            PostgresLimit db = new PostgresLimit(12);
            SharedConnectionGate gate = new SharedConnectionGate(12, db);
            runFleet(pods, gate::query);
            log.info(() -> "pods=" + pods + " served=" + db.served()
                    + " refused=" + db.refused() + " (stable regardless of pods)");
        }
    }

    private static void runFleet(int pods, java.util.function.Supplier<Boolean> q) throws Exception {
        StatementPod[] fleet = new StatementPod[pods];
        Thread[] threads = new Thread[pods];
        for (int i = 0; i < pods; i++) {
            fleet[i] = new StatementPod(4); // each pod: pool of 4 concurrent requests
            final StatementPod pod = fleet[i];
            threads[i] = new Thread(() -> { try { pod.run(q); } catch (InterruptedException ignored) {} });
            threads[i].start();
        }
        for (Thread t : threads) t.join();
    }
}

